#!/usr/bin/env bash
# Project-owned verification: README.md must exist, be non-empty and carry the project title.
set -u
cd "$(dirname "$0")/../.." || exit 1
py -3 -I - <<'PY'
import sys
from pathlib import Path
readme = Path("README.md")
if not readme.is_file():
    print("FAIL: README.md missing", file=sys.stderr); sys.exit(1)
text = readme.read_text(encoding="utf-8")
if not text.strip():
    print("FAIL: README.md empty", file=sys.stderr); sys.exit(1)
if "overgate-rc4-e2e-complex-20261104" not in text:
    print("FAIL: README.md lacks project title", file=sys.stderr); sys.exit(1)
print("PASS: README.md exists, non-empty, title present")
PY
